/** Selection requested from outside the page (palette command). */
const $pendingSelect = atom(null)
/** Locally measured speed/spend, keyed by the model id Hermes reported. */
const $measured = atom({})
/** The newest model.options payload the picker read: { providers }. */
const $options = atom({ providers: null })
/** Models picked for comparison: [{ provider, model }]. */
const $compare = atom([])
/** Where the active data came from: { origin, checking, checkedAt, problem }. */
const $data = atom({ origin: 'bundled', checking: false, checkedAt: 0, problem: null })

let pluginCtx = null

function storageGet(key, fallback) {
  try {
    return pluginCtx?.storage?.get(key, fallback) ?? fallback
  } catch {
    return fallback
  }
}

function storageSet(key, value) {
  try {
    pluginCtx?.storage?.set(key, value)
  } catch {
    /* storage unavailable: keep the in-memory copy */
  }
}

/**
 * The picker's catalog reader. It keeps the full rows for the explanation, and serves the
 * menu rows without settings: a reasoning level or speed picked here would change nothing.
 */
async function catalogRequest(method, params = {}) {
  if (method !== 'model.options') return host.request(method, params)
  const { session_id: slot, ...rest } = params
  const sessionId = String(slot ?? '').slice(CATALOG_SLOT.length)
  const profile = host.state.focusedSessionProfile?.get?.()
  const scope = sessionId ? { session_id: sessionId } : profile ? { profile } : {}
  const res = await host.request(method, { ...rest, ...scope })
  if (!Array.isArray(res?.providers)) return res
  $options.set({ providers: res.providers })
  return {
    ...res,
    providers: res.providers.map(p => ({
      ...p,
      capabilities: Object.fromEntries((p.models ?? []).map(m => [m, { reasoning: false, fast: false }]))
    }))
  }
}

// ---------------------------------------------------------------------------
// Data updates. The bundled copy always works offline; a newer public copy replaces it
// only after it passes the same rules CI applies, and it stays in plugin storage.
// ---------------------------------------------------------------------------

function restoreData() {
  const saved = storageGet('data', null)
  const checkedAt = storageGet('dataCheckedAt', 0)
  const problem = storageGet('dataProblem', null)
  if (saved && validateData(saved).length === 0 && saved.updated >= BUNDLED.updated) {
    useData(saved)
    $data.set({ ...$data.get(), origin: 'github', checkedAt, problem })
  } else {
    $data.set({ ...$data.get(), checkedAt, problem })
  }
}

async function checkData(force = false) {
  if ($data.get().checking) return
  if (!force) {
    if (storageGet('dataUpdates', true) === false) return
    if (Date.now() - storageGet('dataCheckedAt', 0) < DATA_CHECK_MS) return
  }
  $data.set({ ...$data.get(), checking: true })
  let problem = null
  try {
    const res = await fetch(DATA_URL, {
      cache: 'no-cache',
      credentials: 'omit',
      referrerPolicy: 'no-referrer',
      signal: AbortSignal.timeout(DATA_TIMEOUT_MS)
    })
    if (!res.ok) throw new Error(`GitHub answered ${res.status}`)
    const text = await res.text()
    if (text.length > MAX_DATA_CHARS) throw new Error('the file is too large')
    const next = JSON.parse(text)
    const errors = validateData(next)
    if (errors.length) throw new Error(`the file failed validation: ${errors[0]}`)
    if (next.updated >= DATA.updated) {
      useData(next)
      storageSet('data', next)
      $data.set({ ...$data.get(), origin: 'github' })
    }
  } catch (err) {
    problem = String(err?.message ?? err)
  }
  const checkedAt = Date.now()
  storageSet('dataCheckedAt', checkedAt)
  storageSet('dataProblem', problem)
  $data.set({ ...$data.get(), checking: false, checkedAt, problem })
}

function compareKey(pick) {
  return lookup(pick.model)?.id ?? normalizeModelId(pick.model)
}

function toggleCompare(pick) {
  const cur = $compare.get()
  const key = compareKey(pick)
  const next = cur.some(p => compareKey(p) === key) ? cur.filter(p => compareKey(p) !== key) : [...cur, pick].slice(0, MAX_COMPARE)
  $compare.set(next)
  storageSet('compare', next)
}

// ---------------------------------------------------------------------------
// Local measurement: speed (rolling avg TPS) and spend per model, from the
// focused session's live usage stream. Each (session, model) stretch is one
// segment; only calls observed while the plugin runs are counted.
// ---------------------------------------------------------------------------

const MAX_SEGMENTS_PER_MODEL = 40
const MAX_MODELS = 200

function startTracker(ctx) {
  const usageAtom = host.state?.focusedUsage
  if (!usageAtom || typeof usageAtom.subscribe !== 'function') return
  const live = new Map() // sessionId -> { model, baseCalls, baseCost, key }
  let saveTimer = null

  const scheduleSave = () => {
    if (saveTimer) return
    saveTimer = ctx.setTimeout(() => {
      saveTimer = null
      storageSet('measured', $measured.get())
    }, 5000)
  }

  const onUsage = usage => {
    const sid = host.state.focusedSessionId?.get?.()
    const model = host.state.model?.get?.()
    if (!usage || !sid || !model || typeof usage.calls !== 'number') return
    let seg = live.get(sid)
    if (!seg || seg.model !== model || usage.calls < seg.lastCalls) {
      live.set(sid, {
        model,
        baseCalls: usage.calls,
        baseCost: typeof usage.cost_usd === 'number' ? usage.cost_usd : null,
        key: `${sid}@${Date.now()}`,
        lastCalls: usage.calls
      })
      return
    }
    seg.lastCalls = usage.calls
    const calls = usage.calls - seg.baseCalls
    if (calls < 1) return
    const rec = {
      calls,
      cost: typeof usage.cost_usd === 'number' && seg.baseCost !== null ? Math.max(0, usage.cost_usd - seg.baseCost) : null,
      // avg_tps is a rolling average over ~10 calls; skip the first few calls of a
      // segment so a model switch does not credit the previous model's speed.
      tps: calls >= 3 && typeof usage.avg_tps === 'number' && usage.avg_tps > 0 ? usage.avg_tps : null,
      at: Date.now()
    }
    const all = { ...$measured.get() }
    const entry = { ...(all[model] ?? {}) }
    entry[seg.key] = rec
    const keys = Object.keys(entry)
    if (keys.length > MAX_SEGMENTS_PER_MODEL) {
      keys.sort((a, b) => entry[a].at - entry[b].at)
      for (const k of keys.slice(0, keys.length - MAX_SEGMENTS_PER_MODEL)) delete entry[k]
    }
    all[model] = entry
    const models = Object.keys(all)
    if (models.length > MAX_MODELS) {
      const latest = m => Math.max(...Object.values(all[m]).map(r => r.at))
      models.sort((a, b) => latest(a) - latest(b))
      for (const m of models.slice(0, models.length - MAX_MODELS)) delete all[m]
    }
    $measured.set(all)
    scheduleSave()
  }

  const off = usageAtom.listen ? usageAtom.listen(onUsage) : usageAtom.subscribe(onUsage)
  ctx.onDispose(() => {
    off?.()
    storageSet('measured', $measured.get())
  })
}

function summarizeMeasured(all, modelId) {
  const want = normalizeModelId(modelId)
  let calls = 0
  let tpsWeighted = 0
  let tpsCalls = 0
  let cost = 0
  let costCalls = 0
  let segments = 0
  let lastAt = 0
  for (const [reported, segs] of Object.entries(all ?? {})) {
    if (normalizeModelId(reported) !== want) continue
    for (const r of Object.values(segs)) {
      segments += 1
      calls += r.calls
      if (typeof r.at === 'number' && r.at > lastAt) lastAt = r.at
      if (typeof r.tps === 'number') {
        tpsWeighted += r.tps * r.calls
        tpsCalls += r.calls
      }
      if (typeof r.cost === 'number') {
        cost += r.cost
        costCalls += r.calls
      }
    }
  }
  return {
    calls,
    segments,
    lastAt,
    tps: tpsCalls ? tpsWeighted / tpsCalls : null,
    cost: costCalls ? cost : null,
    costPerCall: costCalls ? cost / costCalls : null
  }
}

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

function openUrl(url) {
  if (!url) return
  const os = pluginCtx?.os
  if (os?.openExternal) void os.openExternal(url)
}

/** Tooltip text for a sourced value, or null when the source is unknown. */
function sourceLines(field) {
  const src = field && DATA.sources?.[field.src]
  if (!src) return null
  const lines = [src.title, `Retrieved ${src.retrieved}`]
  if (field.note) lines.push(field.note)
  if (src.note) lines.push(src.note)
  if (src.license) lines.push(`License: ${src.license}`)
  return jsx('div', { style: { whiteSpace: 'pre-line', maxWidth: 340, lineHeight: 1.4 }, children: lines.join('\n') })
}

function SourceTag({ field }) {
  const src = field && DATA.sources?.[field.src]
  if (!src) return null
  return jsx(Tip, {
    label: sourceLines(field),
    children: jsx('button', {
      type: 'button',
      style: { ...S.srcTag, cursor: src.url ? 'pointer' : 'default' },
      onClick: () => openUrl(src.url),
      children: shortSource(field.src, src)
    })
  })
}

function shortSource(id, src) {
  if (id.startsWith('hermes-index')) return `Hermes Index · ${src.retrieved}`
  if (id.startsWith('models-dev')) return `models.dev · ${src.retrieved}`
  if (id === 'editorial') return `maintainer · ${src.retrieved}`
  return `${src.title} · ${src.retrieved}`
}

/** One tag per distinct source, so a card with two values never hides a second source. */
function SourceTags({ fields }) {
  const distinct = [...new Map(fields.filter(Boolean).map(f => [f.src, f])).values()]
  return distinct.map(f => jsx(SourceTag, { field: f }, f.src))
}

function StatCard({ label, value, sub, fields, tag }) {
  const footer = fields?.some(Boolean)
    ? jsx(SourceTags, { fields })
    : tag
      ? jsx('span', { style: S.plainTag, children: tag })
      : null
  return jsxs('div', {
    style: S.card,
    children: [
      jsx('div', { style: S.cardLabel, children: label }),
      jsx('div', { style: { ...S.cardValue, color: value === '—' ? C.text3 : C.text }, children: value }),
      sub ? jsx('div', { style: S.cardSub, children: sub }) : null,
      footer ? jsx('div', { style: { marginTop: 'auto', paddingTop: 2, display: 'flex', gap: 8, flexWrap: 'wrap' }, children: footer }) : null
    ]
  })
}

const SUITES = [
  ['hermes_bench', 'Hermes Bench'],
  ['terminalbench_4', 'TerminalBench 4'],
  ['terminalbench_science', 'TerminalBench Science'],
  ['skillsbench_clean', 'SkillsBench (clean)']
]

function SuiteBars({ field }) {
  const suites = field?.v
  if (!suites) return null
  const rows = SUITES.map(([key, name]) => [name, suites[key]]).filter(([, v]) => typeof v === 'number')
  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 6, maxWidth: 520 },
    children: rows.map(([name, v]) =>
      jsxs(
        'div',
        {
          style: { display: 'grid', gridTemplateColumns: '150px 1fr 44px', alignItems: 'center', gap: 10, fontSize: 12 },
          children: [
            jsx('span', { style: { color: C.text2 }, children: name }),
            jsx('div', {
              style: { height: 6, borderRadius: 3, background: C.hover, overflow: 'hidden' },
              children: jsx('div', { style: { width: `${Math.max(0, Math.min(100, v))}%`, height: '100%', background: C.accent, borderRadius: 3 } })
            }),
            jsx('span', { style: { textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: C.text2 }, children: v.toFixed(1) })
          ]
        },
        name
      )
    )
  })
}

/** Score by reasoning effort. Rendered only when the data file has a sourced curve. */
function ReasoningChart({ curve }) {
  const pts = (curve?.points ?? []).filter(p => typeof p.v === 'number' && p.effort)
  if (pts.length < 2) return null
  const W = 420
  const H = 150
  const pad = { l: 34, r: 12, t: 12, b: 26 }
  const vs = pts.map(p => p.v)
  const lo = Math.max(0, Math.floor((Math.min(...vs) - 5) / 10) * 10)
  const hi = Math.min(100, Math.ceil((Math.max(...vs) + 5) / 10) * 10)
  const x = i => pad.l + (i * (W - pad.l - pad.r)) / (pts.length - 1)
  const y = v => pad.t + ((hi - v) * (H - pad.t - pad.b)) / Math.max(1, hi - lo)
  const ticks = [lo, (lo + hi) / 2, hi]
  return jsxs('svg', {
    viewBox: `0 0 ${W} ${H}`,
    role: 'img',
    'aria-label': `${curve.metric ?? 'Score'} by reasoning effort`,
    style: { width: '100%', maxWidth: W, height: 'auto', display: 'block' },
    children: [
      ...ticks.map(t =>
        jsxs(
          'g',
          {
            children: [
              jsx('line', { x1: pad.l, x2: W - pad.r, y1: y(t), y2: y(t), stroke: C.stroke3, strokeWidth: 1 }),
              jsx('text', { x: pad.l - 6, y: y(t) + 3, textAnchor: 'end', fontSize: 10, fill: C.text3, children: Math.round(t) })
            ]
          },
          `t${t}`
        )
      ),
      jsx('polyline', {
        points: pts.map((p, i) => `${x(i)},${y(p.v)}`).join(' '),
        fill: 'none',
        stroke: C.accent,
        strokeWidth: 2,
        strokeLinejoin: 'round'
      }),
      ...pts.map((p, i) =>
        jsxs(
          'g',
          {
            children: [
              jsx('circle', { cx: x(i), cy: y(p.v), r: 3.5, fill: C.accent }),
              jsx('text', { x: x(i), y: y(p.v) - 8, textAnchor: 'middle', fontSize: 10, fill: C.text2, children: p.v.toFixed(1) }),
              jsx('text', { x: x(i), y: H - 8, textAnchor: 'middle', fontSize: 10.5, fill: C.text3, children: p.effort })
            ]
          },
          `p${i}`
        )
      )
    ]
  })
}

// ---------------------------------------------------------------------------
// Frontier: Hermes Index score against cost per task.
// ---------------------------------------------------------------------------

/** One line saying where a model stands on the frontier, or null without the data. */
function frontierVerdict(entry) {
  if (!entry || !PLOTTED.includes(entry)) return null
  if (FRONTIER.includes(entry)) return { on: true, text: 'On the frontier: nothing cheaper scores higher.' }
  const better = PLOTTED.filter(o => beats(o, entry)).sort((a, b) => a.cost_per_task_usd.v - b.cost_per_task_usd.v)[0]
  return { on: false, text: `Off the frontier: ${better.name} scores ${better.hermes_index.v.toFixed(1)} for ${fmtUsd(better.cost_per_task_usd.v)} per task.` }
}

function FrontierChart({ marked, onPick }) {
  if (PLOTTED.length < 2) return null
  const W = 600
  const H = 320
  const pad = { l: 36, r: 20, t: 22, b: 40 }
  const costs = PLOTTED.map(m => m.cost_per_task_usd.v)
  const lo = Math.log10(Math.min(...costs) / 1.5)
  const hi = Math.log10(Math.max(...costs) * 1.5)
  const top = Math.ceil(Math.max(...PLOTTED.map(m => m.hermes_index.v)) / 10) * 10
  const x = c => pad.l + ((Math.log10(c) - lo) / (hi - lo)) * (W - pad.l - pad.r)
  const y = s => pad.t + ((top - s) / top) * (H - pad.t - pad.b)
  const xTicks = [0.05, 0.1, 0.5, 1, 5, 10].filter(c => Math.log10(c) >= lo && Math.log10(c) <= hi)
  const yTicks = [0, 20, 40, 60, 80, 100].filter(s => s <= top)
  // Labels alternate above and below the line so close neighbours stay readable.
  const labelled = FRONTIER.map((m, i) => ({ m, above: i % 2 === 1 }))
  // A model off the line sits under it, so its label goes below, clear of the line's own labels.
  for (const m of marked) if (PLOTTED.includes(m) && !FRONTIER.includes(m)) labelled.push({ m, above: false })

  return jsxs('svg', {
    viewBox: `0 0 ${W} ${H}`,
    role: 'group',
    'aria-label': `Hermes Index score against cost per task for ${PLOTTED.length} models`,
    style: { width: '100%', maxWidth: W, height: 'auto', display: 'block' },
    children: [
      ...yTicks.map(s =>
        jsxs(
          'g',
          {
            children: [
              jsx('line', { x1: pad.l, x2: W - pad.r, y1: y(s), y2: y(s), stroke: C.stroke3, strokeWidth: 1 }),
              jsx('text', { x: pad.l - 6, y: y(s) + 3, textAnchor: 'end', fontSize: 10, fill: C.text3, children: s })
            ]
          },
          `y${s}`
        )
      ),
      ...xTicks.map(c =>
        jsx('text', { x: x(c), y: H - pad.b + 15, textAnchor: 'middle', fontSize: 10, fill: C.text3, children: `$${c}` }, `x${c}`)
      ),
      jsx('text', { x: (pad.l + W - pad.r) / 2, y: H - 6, textAnchor: 'middle', fontSize: 10.5, fill: C.text3, children: 'Cost per task (log scale)' }),
      jsx('polyline', {
        points: FRONTIER.map(m => `${x(m.cost_per_task_usd.v)},${y(m.hermes_index.v)}`).join(' '),
        fill: 'none',
        stroke: C.accent,
        strokeWidth: 2,
        strokeLinejoin: 'round'
      }),
      ...PLOTTED.map(m => {
        const on = FRONTIER.includes(m)
        const selected = marked.includes(m)
        const open = () => onPick?.(m)
        return jsxs(
          'g',
          {
            role: 'button',
            tabIndex: 0,
            'aria-label': `${m.name}: score ${m.hermes_index.v.toFixed(2)}, ${fmtUsd(m.cost_per_task_usd.v)} per task${on ? ', on the frontier' : ''}`,
            style: { cursor: 'pointer', outline: 'none' },
            onClick: open,
            onKeyDown: e => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault()
                open()
              }
            },
            children: [
              jsx('title', { children: `${m.name}: ${m.hermes_index.v.toFixed(2)} at ${fmtUsd(m.cost_per_task_usd.v)} per task` }),
              // Invisible, larger hit area: the dots are small targets.
              jsx('circle', { cx: x(m.cost_per_task_usd.v), cy: y(m.hermes_index.v), r: 11, fill: 'transparent' }),
              selected ? jsx('circle', { cx: x(m.cost_per_task_usd.v), cy: y(m.hermes_index.v), r: 8, fill: 'none', stroke: C.text, strokeWidth: 1.5 }) : null,
              jsx('circle', { cx: x(m.cost_per_task_usd.v), cy: y(m.hermes_index.v), r: on ? 4.5 : 3.5, fill: on ? C.accent : C.text3 })
            ]
          },
          m.id
        )
      }),
      ...labelled.map(({ m, above }) => {
        const px = x(m.cost_per_task_usd.v)
        // The line rises to the right, so a lower label starts right of its dot, clear of it.
        const anchor = px > W - 90 ? 'end' : !above || px < pad.l + 50 ? 'start' : 'middle'
        return jsx(
          'text',
          {
            x: anchor === 'start' && !above ? px + 6 : px,
            y: y(m.hermes_index.v) + (above ? -12 : 19),
            textAnchor: anchor,
            fontSize: 10.5,
            fontWeight: marked.includes(m) ? 650 : 400,
            fill: marked.includes(m) ? C.text : C.text2,
            style: { pointerEvents: 'none' },
            children: m.name
          },
          `l${m.id}`
        )
      })
    ]
  })
}

function FrontierSection({ marked, onPick }) {
  const first = PLOTTED[0]
  if (!first) return null
  const anyProvisional = PLOTTED.some(m => m.cost_per_task_usd.note)
  return jsxs('div', {
    style: { maxWidth: 600 },
    children: [
      jsxs('div', {
        style: { ...S.h2, display: 'flex', gap: 8, alignItems: 'baseline' },
        children: [jsx('span', { children: 'Score against cost' }), jsx(SourceTag, { field: first.hermes_index })]
      }),
      jsx(FrontierChart, { marked, onPick }),
      jsx('div', {
        style: { ...S.cardSub, marginTop: 4 },
        children: `The line joins models that score higher than every cheaper model. Click a dot to open that model.${
          anyProvisional ? ' Some costs are provisional on the leaderboard.' : ''
        }`
      })
    ]
  })
}

function correctionUrl(modelId, entry) {
  const params = new URLSearchParams({
    template: 'correction.yml',
    title: `Correction: ${entry?.name ?? modelId}`,
    model: entry?.id ?? String(modelId)
  })
  return `${REPO_URL}/issues/new?${params.toString()}`
}

// ---------------------------------------------------------------------------
// "Use this model": the same config.set request Hermes' own picker sends. In an open chat
// it is scoped to that chat (--session), so it never rewrites the profile default. A
// guarded switch (data policy, expensive model) asks through Hermes' shared confirm dialog.
// ---------------------------------------------------------------------------

const $switching = atom('')

async function switchModel(sel, label) {
  if ($switching.get()) return
  const sessionId = host.state.focusedSessionId?.get?.() || ''
  const send = confirmed =>
    host.request('config.set', {
      ...(sessionId ? { session_id: sessionId } : {}),
      key: 'model',
      value: `${sel.model} --provider ${sel.provider}${sessionId ? ' --session' : ''}`,
      ...(confirmed ? { confirm_expensive_model: true } : {})
    })
  const finish = res => {
    void queryClient.invalidateQueries({ queryKey: ['model-options'] })
    host.notify?.({
      kind: res?.deferred ? 'info' : 'success',
      message: res?.deferred ? `${label} will be used from the next turn.` : `Now using ${label}${sessionId ? ' in this chat' : ''}.`
    })
  }
  const failed = `Could not switch to ${label}.`
  $switching.set(sel.model)
  try {
    const res = await send(false)
    if (!res?.confirm_required) return finish(res)
    if (typeof SDK.surfaceModelSwitchConfirm === 'function') {
      await SDK.surfaceModelSwitchConfirm({
        confirmMessage: res.confirm_message,
        failureMessage: failed,
        isStale: () => (host.state.focusedSessionId?.get?.() || '') !== sessionId,
        model: sel.model,
        requestConfirmed: () => send(true),
        finish
      })
    } else {
      host.notify?.({ kind: 'info', message: res.confirm_message || `Hermes asks you to confirm ${label}. Pick it in the chat's model menu.` })
    }
  } catch (err) {
    host.notify?.({ kind: 'error', message: `${failed} ${String(err?.message ?? '').slice(0, 160)}`.trim() })
  } finally {
    $switching.set('')
  }
}

function UseModelButton({ sel, isCurrent, label }) {
  const switching = useValue($switching)
  const gateway = useValue(host.state.gateway)
  const offline = gateway !== 'open'
  const why = isCurrent
    ? 'Your chat already uses this model.'
    : !sel.provider
      ? 'None of your providers offers this model.'
      : offline
        ? 'Hermes is not connected.'
        : 'Switch your chat to this model.'
  const button = jsx(Button, {
    size: 'sm',
    variant: 'default',
    disabled: isCurrent || !sel.provider || offline || Boolean(switching),
    onClick: () => void switchModel(sel, label),
    children: switching === sel.model ? 'Switching…' : isCurrent ? 'In use' : 'Use this model'
  })
  return jsx(Tip, { label: why, children: jsx('span', { style: { display: 'inline-flex' }, children: button }) })
}

function Detail({ sel, providerRow, measuredAll, currentModel, onPick, compare }) {
  if (!sel) {
    return jsx('div', {
      style: { ...S.detail, display: 'flex', alignItems: 'center', justifyContent: 'center' },
      children: jsx(EmptyState, { title: 'Pick a model', description: 'Choose a model on the left to see what it is good at, what it costs and where each number comes from.' })
    })
  }
  const entry = lookup(sel.model)
  const caps = providerRow?.capabilities?.[sel.model]
  const pricing = providerRow?.pricing?.[sel.model]
  const measured = summarizeMeasured(measuredAll, sel.model)
  const isCurrent = sel.model === currentModel
  const rank = entry ? rankOf(entry) : null
  const verdict = frontierVerdict(entry)
  const inCompare = compare.some(p => compareKey(p) === compareKey(sel))
  const compareFull = !inCompare && compare.length >= MAX_COMPARE

  const abilities = new Map()
  for (const a of entry?.abilities?.v ?? []) abilities.set(a, 'data')
  if (caps?.reasoning) abilities.set('reasoning', abilities.has('reasoning') ? 'both' : 'hermes')
  if (caps?.fast) abilities.set('fast', 'hermes')

  const hermesPrice =
    pricing && (pricing.input || pricing.output)
      ? pricing.free
        ? `${providerRow.name}: free`
        : `${providerRow.name} in Hermes: ${pricing.input || '?'} in / ${pricing.output || '?'} out per Mtok`
      : null

  const compareButton = jsx(Button, {
    size: 'sm',
    variant: 'outline',
    disabled: compareFull,
    onClick: () => toggleCompare(sel),
    children: inCompare ? 'Remove from compare' : compareFull ? `Compare is full (${MAX_COMPARE})` : 'Add to compare'
  })

  const header = jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 6 },
    children: [
      jsxs('div', {
        style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' },
        children: [
          jsx('h1', { style: { fontSize: 20, fontWeight: 650, margin: 0 }, children: entry?.name ?? sel.model }),
          isCurrent ? jsx(Badge, { variant: 'default', children: 'In use' }) : null,
          rank ? jsx(Badge, { variant: 'muted', children: `#${rank} of ${RANKED.length} on Hermes Index` }) : null,
          verdict?.on ? jsx(Badge, { variant: 'success', children: 'On the frontier' }) : null,
          jsxs('span', {
            style: { marginLeft: 'auto', display: 'inline-flex', gap: 8, alignItems: 'center' },
            children: [compareButton, jsx(UseModelButton, { sel, isCurrent, label: entry?.name ?? sel.model })]
          })
        ]
      }),
      jsx('div', {
        style: S.muted,
        children: [entry?.vendor, providerRow?.name ? `via ${providerRow.name}` : null, sel.model].filter(Boolean).join(' · ')
      }),
      entry?.summary
        ? jsxs('div', {
            style: { fontSize: 13.5, color: C.text, display: 'flex', gap: 8, alignItems: 'baseline', flexWrap: 'wrap', marginTop: 2 },
            children: [jsx('span', { children: entry.summary.v }), jsx(SourceTag, { field: entry.summary })]
          })
        : null,
      verdict ? jsx('div', { style: { fontSize: 12.5, color: C.text2 }, children: verdict.text }) : null
    ]
  })

  const measuredCards = [
    jsx(
      StatCard,
      {
        label: 'Avg speed (your runs)',
        value: measured.tps ? `${Math.round(measured.tps)} tok/s` : '—',
        sub: measured.calls
          ? `Measured by Hermes on this machine over ${measured.calls} API calls in ${measured.segments} session${measured.segments === 1 ? '' : 's'}.`
          : 'Use this model in a chat and Hermes measures its speed here.',
        tag: measured.tps ? `Hermes on this machine · ${fmtDate(measured.lastAt)}` : null
      },
      'tps'
    ),
    jsx(
      StatCard,
      {
        label: 'Your spend',
        value: measured.cost !== null ? fmtUsd(measured.cost) : '—',
        sub:
          measured.costPerCall !== null
            ? `${fmtUsd(measured.costPerCall)} per API call, from Hermes' own cost tracking.`
            : 'Shown once Hermes reports a cost for this model.',
        tag: measured.cost !== null ? `Hermes on this machine · ${fmtDate(measured.lastAt)}` : null
      },
      'spend'
    )
  ]

  if (!entry) {
    return jsxs('div', {
      style: S.detail,
      children: [
        header,
        jsxs('div', {
          style: { ...S.card, marginTop: 16, maxWidth: 620 },
          children: [
            jsx('div', { style: { fontWeight: 600 }, children: 'No sourced data for this model yet' }),
            jsx('div', {
              style: S.cardSub,
              children:
                'The explainer only shows values that have a public source and date. You can suggest this model; the maintainer adds it to the data file with sources.'
            }),
            jsx('div', {
              style: { marginTop: 6 },
              children: jsx(Button, { size: 'sm', variant: 'outline', onClick: () => openUrl(correctionUrl(sel.model, null)), children: 'Suggest data for this model' })
            })
          ]
        }),
        hermesPrice ? jsx('div', { style: { ...S.muted, marginTop: 12 }, children: hermesPrice }) : null,
        jsx('div', { style: S.grid, children: measuredCards }),
        abilities.size ? jsx(AbilityChips, { abilities, entry }) : null,
        jsx(FrontierSection, { marked: [], onPick })
      ]
    })
  }

  const cpt = entry.cost_per_task_usd
  return jsxs('div', {
    style: S.detail,
    children: [
      header,
      jsxs('div', {
        style: S.grid,
        children: [
          jsx(StatCard, {
            label: 'Hermes Index',
            value: entry.hermes_index ? entry.hermes_index.v.toFixed(2) : '—',
            sub: 'Agentic score in the Hermes harness, high reasoning effort.',
            fields: [entry.hermes_index]
          }),
          jsx(StatCard, {
            label: 'Cost per task',
            value: cpt ? fmtUsd(cpt.v) + (cpt.note ? '*' : '') : '—',
            sub: cpt?.note ? 'Provisional on the leaderboard.' : 'Mean over Hermes Index tasks.',
            fields: [cpt]
          }),
          jsx(StatCard, { label: 'Context window', value: fmtTokens(entry.context_tokens?.v), sub: 'Tokens in + out per request.', fields: [entry.context_tokens] }),
          jsx(StatCard, {
            label: 'Max input',
            value: fmtTokens(entry.max_input_tokens?.v ?? entry.context_tokens?.v),
            sub: entry.max_input_tokens ? 'Prompt limit.' : 'No separate input cap listed; same as context.',
            fields: [entry.max_input_tokens ?? entry.context_tokens]
          }),
          jsx(StatCard, { label: 'Max output', value: fmtTokens(entry.max_output_tokens?.v), sub: 'Tokens per reply.', fields: [entry.max_output_tokens] }),
          jsx(StatCard, {
            label: 'Price (per Mtok)',
            value: `${fmtPrice(entry.price_input_per_mtok?.v)} / ${fmtPrice(entry.price_output_per_mtok?.v)}`,
            sub: hermesPrice ?? 'Input / output, reference host. Your provider may differ.',
            fields: [entry.price_input_per_mtok, entry.price_output_per_mtok]
          }),
          ...measuredCards
        ]
      }),
      jsx(FrontierSection, { marked: [entry], onPick }),
      entry.hermes_index_suites
        ? jsxs('div', {
            children: [
              jsxs('div', {
                style: { ...S.h2, display: 'flex', gap: 8, alignItems: 'baseline' },
                children: [jsx('span', { children: 'Intelligence by suite' }), jsx(SourceTag, { field: entry.hermes_index_suites })]
              }),
              jsx(SuiteBars, { field: entry.hermes_index_suites })
            ]
          })
        : null,
      entry.reasoning_curve
        ? jsxs('div', {
            children: [
              jsxs('div', {
                style: { ...S.h2, display: 'flex', gap: 8, alignItems: 'baseline' },
                children: [
                  jsx('span', { children: `${entry.reasoning_curve.metric ?? 'Score'} by reasoning effort` }),
                  jsx(SourceTag, { field: entry.reasoning_curve })
                ]
              }),
              jsx(ReasoningChart, { curve: entry.reasoning_curve })
            ]
          })
        : null,
      jsx(AbilityChips, { abilities, entry }),
      jsxs('div', {
        style: { marginTop: 28, display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' },
        children: [
          jsx(Button, {
            size: 'sm',
            variant: 'outline',
            onClick: () => openUrl(correctionUrl(sel.model, entry)),
            children: 'Report a correction'
          }),
          jsx('span', { style: S.muted, children: `Data file dated ${DATA.updated ?? '—'}. Hover a source to see where a value comes from.` })
        ]
      })
    ]
  })
}

function AbilityChips({ abilities, entry }) {
  if (!abilities.size) return null
  return jsxs('div', {
    children: [
      jsxs('div', {
        style: { ...S.h2, display: 'flex', gap: 8, alignItems: 'baseline' },
        children: [jsx('span', { children: 'Abilities' }), entry?.abilities ? jsx(SourceTag, { field: entry.abilities }) : null]
      }),
      jsx('div', {
        style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
        children: [...abilities.entries()].map(([a, from]) =>
          jsx(
            Tip,
            {
              label: from === 'hermes' ? 'Reported by Hermes for this provider' : from === 'both' ? 'In the data file and reported by Hermes' : 'From the data file source',
              children: jsx('span', { style: S.chip, children: ABILITY_LABEL[a] ?? a })
            },
            a
          )
        )
      })
    ]
  })
}

// ---------------------------------------------------------------------------
// Compare
// ---------------------------------------------------------------------------

const COMPARE_ROWS = [
  { label: 'Hermes Index', field: e => e?.hermes_index, text: v => v.toFixed(2), better: 'high' },
  ...SUITES.map(([key, label]) => ({
    label,
    field: e => (typeof e?.hermes_index_suites?.v?.[key] === 'number' ? { ...e.hermes_index_suites, v: e.hermes_index_suites.v[key] } : null),
    text: v => v.toFixed(1),
    better: 'high'
  })),
  { label: 'Cost per task', field: e => e?.cost_per_task_usd, text: fmtUsd, better: 'low' },
  { label: 'Context window', field: e => e?.context_tokens, text: fmtTokens, better: 'high' },
  { label: 'Max input', field: e => e?.max_input_tokens ?? e?.context_tokens, text: fmtTokens, better: 'high' },
  { label: 'Max output', field: e => e?.max_output_tokens, text: fmtTokens, better: 'high' },
  { label: 'Input price (per Mtok)', field: e => e?.price_input_per_mtok, text: fmtPrice, better: 'low' },
  { label: 'Output price (per Mtok)', field: e => e?.price_output_per_mtok, text: fmtPrice, better: 'low' },
  { label: 'Abilities', field: e => e?.abilities, text: v => v.map(a => ABILITY_LABEL[a] ?? a).join(', ') }
]

/** The strongest numeric value of a row, or null when there is nothing to tell apart. */
function bestOf(values, better) {
  const nums = values.filter(v => typeof v === 'number')
  if (!better || nums.length < 2 || new Set(nums).size < 2) return null
  return better === 'high' ? Math.max(...nums) : Math.min(...nums)
}

function CompareRow({ label, cells }) {
  return jsxs('tr', {
    children: [
      jsx('th', { scope: 'row', style: S.rowHead, children: label }),
      ...cells.map((cell, i) => jsx('td', { style: { ...S.td, ...cell.style }, children: cell.children }, i))
    ]
  })
}

function CompareView({ picks, providers, measuredAll, onOpen, onPick }) {
  if (!picks.length) {
    return jsx('div', {
      style: { ...S.detail, display: 'flex', alignItems: 'center', justifyContent: 'center' },
      children: jsx(EmptyState, {
        title: 'Nothing to compare yet',
        description: `Open a model and choose Add to compare. You can compare up to ${MAX_COMPARE} side by side.`
      })
    })
  }
  const columns = picks.map(pick => ({
    pick,
    entry: lookup(pick.model),
    provider: providers.find(p => p.slug === pick.provider),
    measured: summarizeMeasured(measuredAll, pick.model)
  }))
  const sourced = []
  const rows = COMPARE_ROWS.map(row => {
    const fields = columns.map(c => row.field(c.entry))
    sourced.push(...fields.filter(Boolean))
    const best = bestOf(fields.map(f => f?.v), row.better)
    const cells = fields.map(f => ({
      style: f?.v === best && best !== null ? { color: C.text, fontWeight: 650 } : null,
      children: f ? jsx(Tip, { label: sourceLines(f), children: jsx('span', { children: row.text(f.v) + (f.note ? '*' : '') }) }) : '—'
    }))
    return jsx(CompareRow, { label: row.label, cells }, row.label)
  })
  const speeds = columns.map(c => c.measured.tps)
  const bestSpeed = bestOf(speeds, 'high')
  const frontier = columns.map(c => frontierVerdict(c.entry))

  return jsxs('div', {
    style: S.detail,
    children: [
      jsx('div', { style: S.tableWrap, children: jsxs('table', {
        style: S.table,
        children: [
          jsx('thead', {
            children: jsxs('tr', {
              children: [
                jsx('td', { style: { ...S.rowHead, borderBottom: `1px solid ${C.stroke}` } }),
                ...columns.map(({ pick, entry, provider }) => {
                  const name = entry?.name ?? pick.model
                  return jsx(
                    'th',
                    {
                      scope: 'col',
                      style: S.th,
                      children: jsxs('div', {
                        style: { display: 'flex', flexDirection: 'column', gap: 2 },
                        children: [
                          jsxs('div', {
                            style: { display: 'flex', gap: 6, alignItems: 'flex-start', justifyContent: 'space-between' },
                            children: [
                              jsx('button', { type: 'button', style: S.link, onClick: () => onOpen(pick), children: name }),
                              jsx('button', {
                                type: 'button',
                                style: S.iconBtn,
                                'aria-label': `Remove ${name} from compare`,
                                onClick: () => toggleCompare(pick),
                                children: jsx(Codicon, { name: 'close', size: 12 })
                              })
                            ]
                          }),
                          jsx('div', { style: { ...S.muted, fontWeight: 400, fontSize: 11 }, children: [entry?.vendor, provider ? `via ${provider.name}` : null].filter(Boolean).join(' · ') || '—' })
                        ]
                      })
                    },
                    compareKey(pick)
                  )
                })
              ]
            })
          }),
          jsxs('tbody', {
            children: [
              ...rows,
              jsx(CompareRow, {
                label: 'Frontier',
                cells: frontier.map(v => ({ children: v ? (v.on ? 'On the line' : 'Off the line') : '—' }))
              }, 'frontier'),
              jsx(CompareRow, {
                label: 'Avg speed (your runs)',
                cells: speeds.map((tps, i) => ({
                  style: tps !== null && tps === bestSpeed ? { color: C.text, fontWeight: 650 } : null,
                  children: tps ? jsx(Tip, { label: `Measured by Hermes on this machine, last on ${fmtDate(columns[i].measured.lastAt)}`, children: jsx('span', { children: `${Math.round(tps)} tok/s` }) }) : '—'
                }))
              }, 'speed'),
              jsx(CompareRow, {
                label: 'Your spend',
                cells: columns.map(c => ({
                  children: c.measured.cost !== null ? jsx(Tip, { label: `From Hermes' cost tracking, last on ${fmtDate(c.measured.lastAt)}`, children: jsx('span', { children: fmtUsd(c.measured.cost) }) }) : '—'
                }))
              }, 'spend')
            ]
          })
        ]
      }) }),
      jsxs('div', {
        style: { ...S.cardSub, marginTop: 8, display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'baseline' },
        children: [
          jsx('span', { children: `Bold marks the strongest value in a row.${sourced.some(f => f.note) ? ' * is provisional on the leaderboard.' : ''} Hover a value for its source.` }),
          jsx(SourceTags, { fields: sourced.map(f => ({ src: f.src })) })
        ]
      }),
      jsx(FrontierSection, { marked: columns.map(c => c.entry).filter(Boolean), onPick })
    ]
  })
}

// ---------------------------------------------------------------------------
// The picker. This is Hermes' own menu, so sections, names, -fast grouping, favorites
// and the Edit Models shortlist match the composer. The controller gives a selection a
// different meaning here: it opens the explanation; "Use this model" does the switch. The menu
// portals into this column, so it scrolls, hides and unmounts with the page.
// ---------------------------------------------------------------------------

const keepOpen = () => {}

function PickerPane({ sel, sessionId, onSelect }) {
  const [box, setBox] = useState(null)
  const [surface, setSurface] = useState(null)
  const [width, setWidth] = useState(0)
  const [height, setHeight] = useState(null)

  // Measure now as well: an observer only reports once the page next paints.
  useEffect(() => {
    if (!box) return
    setWidth(box.clientWidth)
    if (typeof ResizeObserver !== 'function') return
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width))
    ro.observe(box)
    return () => ro.disconnect()
  }, [box])

  // The menu floats, so it reserves its own height in this column.
  useEffect(() => {
    if (!surface) return
    setHeight(surface.offsetHeight)
    if (typeof ResizeObserver !== 'function') return
    const ro = new ResizeObserver(() => setHeight(surface.offsetHeight))
    ro.observe(surface)
    return () => ro.disconnect()
  }, [surface])

  const controller = useMemo(
    () => ({
      allowSpeed: false,
      applyPreset: () => {},
      // effortPending keeps the selected row free of a reasoning chip.
      current: { effort: '', effortPending: true, fast: false, model: sel?.model ?? '', provider: sel?.provider ?? '' },
      presetFor: () => ({}),
      select: (model, provider) => onSelect({ provider, model }),
      setOptions: () => {}
    }),
    [sel?.model, sel?.provider, onSelect]
  )

  return jsx('div', {
    ref: setBox,
    style: height ? { ...S.picker, height } : S.picker,
    'data-model-explainer-picker': '',
    children:
      box && width
        ? jsx(ModelMenuCloseContext.Provider, {
            value: keepOpen,
            children: jsxs(DropdownMenu, {
              open: true,
              modal: false,
              children: [
                jsx(DropdownMenuTrigger, { asChild: true, children: jsx('span', { 'aria-hidden': true, style: S.pickerAnchor }) }),
                jsx(DropdownMenuContent, {
                  ref: setSurface,
                  portalContainer: box,
                  side: 'bottom',
                  align: 'start',
                  sideOffset: 0,
                  collisionPadding: 0,
                  avoidCollisions: false,
                  style: { ...S.pickerSurface, width },
                  children: jsx(ModelCatalogMenu, {
                    controller,
                    request: catalogRequest,
                    sessionId: `${CATALOG_SLOT}${sessionId ?? ''}`
                  })
                })
              ]
            })
          })
        : null
  })
}

function RankRow({ model, place, active, onPick }) {
  const [hover, setHover] = useState(false)
  return jsxs('button', {
    type: 'button',
    'aria-current': active ? 'true' : undefined,
    style: { ...S.rankRow, background: active ? C.accentSoft : hover ? C.hover : 'none', color: active || hover ? C.text : S.rankRow.color },
    onClick: () => onPick(model),
    onMouseEnter: () => setHover(true),
    onMouseLeave: () => setHover(false),
    onFocus: () => setHover(true),
    onBlur: () => setHover(false),
    children: [
      jsx('span', { style: { width: 16, textAlign: 'right', color: C.text3, fontVariantNumeric: 'tabular-nums' }, children: place }),
      jsx('span', { style: { flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, children: model.name }),
      jsx('span', { style: { color: C.text3, fontVariantNumeric: 'tabular-nums' }, children: model.hermes_index.v.toFixed(1) })
    ]
  })
}

/** Every model the data file scores, best first. */
function RankList({ sel, onPick }) {
  const active = sel ? lookup(sel.model) : null
  const first = RANKED[0]
  if (!first) return null
  return jsxs('div', {
    style: S.ranks,
    children: [
      jsxs('div', {
        style: S.ranksHead,
        children: [jsx('span', { children: 'Ranked by Hermes Index' }), jsx(SourceTag, { field: first.hermes_index })]
      }),
      ...RANKED.map((m, i) => jsx(RankRow, { model: m, place: i + 1, active: m === active, onPick }, m.id))
    ]
  })
}

function DataBar({ compact }) {
  const info = useValue($data)
  const [auto, setAuto] = useState(() => storageGet('dataUpdates', true) !== false)
  const copy = info.origin === 'github' ? 'public file' : 'bundled copy'
  const status = info.checking
    ? 'Checking GitHub…'
    : info.problem
      ? `Update check failed, using the ${copy}.`
      : info.checkedAt
        ? `Checked ${fmtDate(info.checkedAt)}.`
        : 'Not checked yet.'
  return jsxs('div', {
    style: S.dataBar,
    children: [
      jsxs('div', {
        style: S.dataRow,
        children: [
          jsx(Tip, {
            label: jsx('div', {
              style: { whiteSpace: 'pre-line', maxWidth: 340, lineHeight: 1.4 },
              children: [status, info.problem, `Public file: ${DATA_URL}`].filter(Boolean).join('\n')
            }),
            children: jsx('span', { children: `Data ${DATA.updated ?? '—'}, ${copy}` })
          }),
          jsx(Tip, {
            label: 'Check GitHub for a newer data file',
            children: jsx(Button, {
              size: 'icon-sm',
              variant: 'ghost',
              'aria-label': 'Check GitHub for a newer data file',
              disabled: info.checking,
              onClick: () => void checkData(true),
              children: jsx(Codicon, { name: 'refresh', spinning: info.checking })
            })
          })
        ]
      }),
      compact ? null : jsx('div', { 'aria-live': 'polite', style: { color: info.problem ? C.warn : C.text3 }, children: status }),
      compact ? null : jsxs('label', {
        style: { display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' },
        children: [
          jsx(Switch, {
            checked: auto,
            onCheckedChange: v => {
              setAuto(v)
              storageSet('dataUpdates', v)
            }
          }),
          jsx('span', { children: 'Check daily when this page opens' })
        ]
      })
    ]
  })
}

function ViewTabs({ view, onChange, count }) {
  const tab = (id, label) =>
    jsx(
      'button',
      {
        type: 'button',
        role: 'tab',
        'aria-selected': view === id,
        style: view === id ? { ...S.tab, ...S.tabActive } : S.tab,
        onClick: () => onChange(id),
        children: label
      },
      id
    )
  return jsxs('div', { role: 'tablist', 'aria-label': 'View', style: S.tabs, children: [tab('detail', 'Details'), tab('compare', count ? `Compare (${count})` : 'Compare')] })
}

function ExplainerPage() {
  const opts = useValue($options)
  const measuredAll = useValue($measured)
  const pending = useValue($pendingSelect)
  const compare = useValue($compare)
  const currentModel = useValue(host.state.model)
  const sessionId = useValue(host.state.focusedSessionId)
  const gateway = useValue(host.state.gateway)
  useValue($data) // A newer data file re-renders everything derived from it.
  const [sel, setSel] = useState(null)
  const [view, setView] = useState('detail')

  // Pages can sit in a narrow split tile, so follow the page's width, not the window's.
  const pageRef = useRef(null)
  const [stacked, setStacked] = useState(false)

  useEffect(() => {
    const el = pageRef.current
    if (!el || typeof ResizeObserver !== 'function') return
    const ro = new ResizeObserver(([e]) => setStacked(e.contentRect.width < NARROW_PAGE_PX))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  useEffect(() => {
    void checkData()
  }, [])

  // Opened before the gateway connected? Have the picker read again as soon as it does.
  const gatewayWas = useRef(gateway)
  useEffect(() => {
    if (gateway === 'open' && gatewayWas.current !== 'open') void queryClient.invalidateQueries({ queryKey: ['model-options'] })
    gatewayWas.current = gateway
  }, [gateway])

  const providers = useMemo(() => (opts.providers ?? []).filter(p => p.slug !== 'moa' && Array.isArray(p.models)), [opts.providers])

  // Initial / requested selection: the pending request, else the model in use.
  useEffect(() => {
    if (!providers.length) return
    const want = pending ?? (sel ? null : { model: currentModel })
    if (!want?.model) return
    const row =
      providers.find(p => p.slug === want.provider && p.models.includes(want.model)) ??
      providers.find(p => p.is_current && p.models.includes(want.model)) ??
      providers.find(p => p.models.includes(want.model))
    setSel({ provider: row?.slug ?? want.provider ?? '', model: want.model })
    if (pending) {
      setView('detail')
      $pendingSelect.set(null)
    }
  }, [providers, pending, currentModel])

  const open = pick => {
    setSel(pick)
    setView('detail')
  }
  const onSelect = useRef(open)
  onSelect.current = open
  const select = useMemo(() => pick => onSelect.current(pick), [])

  // Open a charted model: stay in the current provider section when it has one.
  const pickEntry = target => {
    const inRow = row => row.models.find(m => lookup(m) === target)
    const current = providers.find(p => p.slug === sel?.provider)
    const row = current && inRow(current) ? current : providers.find(inRow)
    open(row ? { provider: row.slug, model: inRow(row) } : { provider: '', model: target.id })
  }

  const providerRow = sel ? providers.find(p => p.slug === sel.provider) : null

  return jsxs('div', {
    ref: pageRef,
    style: stacked ? { ...S.page, flexDirection: 'column' } : S.page,
    children: [
      jsxs('div', {
        style: stacked ? S.listStacked : S.list,
        children: [
          jsx(PickerPane, { sel, sessionId, onSelect: select }),
          stacked ? null : jsx(RankList, { sel, onPick: pickEntry }),
          jsx(DataBar, { compact: stacked })
        ]
      }),
      jsxs('div', {
        style: S.column,
        children: [
          jsx(ViewTabs, { view, onChange: setView, count: compare.length }),
          view === 'compare'
            ? jsx(CompareView, { picks: compare, providers, measuredAll, onOpen: open, onPick: pickEntry })
            : jsx(Detail, { sel, providerRow, measuredAll, currentModel, onPick: pickEntry, compare })
        ]
      })
    ]
  })
}


// ---------------------------------------------------------------------------
// Registration
// ---------------------------------------------------------------------------

export default {
  id: ID,
  name: 'Model Explainer',
  description: 'Explains every model in your picker: Hermes Index score, cost per task, limits, price, abilities and your own measured speed, each value with a source and date. Compare up to four.',
  register(ctx) {
    pluginCtx = ctx
    $measured.set(storageGet('measured', {}) ?? {})
    $compare.set((storageGet('compare', []) ?? []).slice(0, MAX_COMPARE))
    restoreData()
    ctx.onDispose(() => {
      pluginCtx = null
    })

    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: ROUTE }, render: () => jsx(ExplainerPage, {}) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: ROUTE, label: 'Models', codicon: 'graph' } },
      {
        id: 'open',
        area: PALETTE_AREA,
        data: { id: `${ID}.open`, label: 'Model Explainer: Open', keywords: ['model', 'explainer', 'compare', 'hermes index'], run: () => host.navigate(ROUTE) }
      },
      {
        id: 'explain-current',
        area: PALETTE_AREA,
        data: {
          id: `${ID}.explain-current`,
          label: 'Model Explainer: Explain current model',
          keywords: ['model', 'current', 'explain'],
          run: () => {
            const model = host.state.model.get()
            if (model) $pendingSelect.set({ model })
            host.navigate(ROUTE)
          }
        }
      },
      {
        id: 'picker-badge',
        area: MODEL_MENU_ROW_AREA,
        data: {
          decorate: ({ model }) => {
            const e = lookup(model)
            return e?.hermes_index ? { badge: `HI ${Math.round(e.hermes_index.v)}` } : null
          }
        }
      }
    ])

    startTracker(ctx)
  }
}
